local FLOG_ERROR = _G.FLOG_ERROR

local GMCharacterUtil = {}

---@param Widget UComboBoxString
---@param DataList table
function GMCharacterUtil:AddComboBoxItem(Widget, DataList)
    if Widget == nil or DataList == nil then
        FLOG_ERROR("[GMCharacterUtil:AddComboBoxItem] Widget[%s] or DataList is nil", Widget:GetName() or "nil")
        return
    end

    Widget:ClearOptions()
    for i, v in ipairs(DataList) do
        Widget:AddOption(v)
    end
end

return GMCharacterUtil